int handle_ioctl(unsigned long cmd, unsigned long arg, struct fb_info *info, int type, int fb_depth, unsigned long fb_size) {
    void __user *argp = (void __user *)(uintptr_t)arg;
    int ret = 0;

    switch (cmd) {
        case FBIOGET_VBLANK:
        case FBIOGET_FPLINE:
        case FBIOGET_CON2FBMAP:
        case FBIOPUT_CON2FBMAP:
            break;
        case FBIOGETCMAP:
        {
            struct fb_cmap __user *key = argp;
            u16 __user *red = NULL, *green = NULL, *blue = NULL, *transp = NULL;
            int start, len;

            if (copy_from_user(&start, &key->start, sizeof(key->start)) ||
                copy_from_user(&len, &key->len, sizeof(key->len)))
                return -EFAULT;

            red = key->red;
            green = key->green;
            blue = key->blue;
            transp = key->transp;

            if (start + len > 256)
                return -EINVAL;

            if (copy_to_user(red, info->cmap.red + start, len * sizeof(u16)) ||
                copy_to_user(green, info->cmap.green + start, len * sizeof(u16)) ||
                copy_to_user(blue, info->cmap.blue + start, len * sizeof(u16)))
                return -EFAULT;

            if (transp && copy_to_user(transp, info->cmap.transp + start, len * sizeof(u16)))
                return -EFAULT;
            break;
        }
        case FBIOPUTCMAP:
        {
            struct fb_cmap __user *key = argp;
            u16 __user *red = NULL, *green = NULL, *blue = NULL, *transp = NULL;
            int start, len;

            if (copy_from_user(&start, &key->start, sizeof(key->start)) ||
                copy_from_user(&len, &key->len, sizeof(key->len)))
                return -EFAULT;

            red = key->red;
            green = key->green;
            blue = key->blue;
            transp = key->transp;

            if (start + len > 256)
                return -EINVAL;

            if (copy_from_user(info->cmap.red + start, red, len * sizeof(u16)) ||
                copy_from_user(info->cmap.green + start, green, len * sizeof(u16)) ||
                copy_from_user(info->cmap.blue + start, blue, len * sizeof(u16)))
                return -EFAULT;

            if (transp && copy_from_user(info->cmap.transp + start, transp, len * sizeof(u16)))
                return -EFAULT;
            break;
        }
        case FBIOGET_VSCREENINFO:
        {
            struct fb_var_screeninfo __user *var = argp;

            if (copy_to_user(var, &info->var, sizeof(struct fb_var_screeninfo)))
                return -EFAULT;
            break;
        }
        default:
            return -EINVAL;
    }

    return ret;
}

int handle_ioctl_cmd(unsigned long cmd, unsigned long arg,
                     struct fb_info *info, int type, int fb_depth,
                     unsigned long fb_size) {
    int ret = 0;

    switch (cmd) {
        case FBIOGET_FSCREENINFO: {
            struct fb_fix_screeninfo finfo;
            strncpy(finfo.id, "framebuffer", sizeof(finfo.id) - 1);
            finfo.id[sizeof(finfo.id) - 1] = '\0';
            finfo.type = type;
            finfo.type_aux = 0;
            finfo.virту_0ffset = 0;
            finfo.xpanstep = 0;
            finfo.ypanstep = 0;
            finfo.ywrapstep = 0;
            finfo.accel = 0;
            finfo.size = fb_size;
            finfo.pages = 1;
            finfo.line_length = info->var.xres * (fb_depth / 8);

            if (copy_to_user((void __user *)arg, &finfo, sizeof(finfo)))
                return -EFAULT;
            break;
        }
        case FBIOGET_VSCREENINFO: {
            struct fb_var_screeninfo var = info->var;
            var.xres = info->var.xres;
            var.yres = info->var.yres;
            var.xres_virtual = info->var.xres;
            var.yres_virtual = info->var.yres;
            var.bits_per_pixel = fb_depth;
            var.red.length = 0;
            var.green.length = 0;
            var.blue.length = 0;
            var.transp.length = 0;

            if (copy_to_user((void __user *)arg, &var, sizeof(var)))
                return -EFAULT;
            break;
        }
        case FBIOPUTCMAP: {
            struct fb_cmap cmap;
            if (copy_from_user(&cmap, (void __user *)arg, sizeof(cmap)))
                return -EFAULT;

            if (cmap.start + cmap.len > 256)
                return -EINVAL;

            for (int i = 0; i < cmap.len; i++) {
                info->cmap.red[i + cmap.start] = cmap.red[i];
                info->cmap.green[i + cmap.start] = cmap.green[i];
                info->cmap.blue[i + cmap.start] = cmap.blue[i];
                info->cmap.transp[i + cmap.start] = cmap.transp[i];
            }
            break;
        }
        case FBIOGETCMAP: {
            struct fb_cmap cmap;
            if (copy_from_user(&cmap, (void __user *)arg, sizeof(cmap)))
                return -EFAULT;

            if (cmap.start + cmap.len > 256)
                return -EINVAL;

            for (int i = 0; i < cmap.len; i++) {
                cmap.red[i] = info->cmap.red[i + cmap.start];
                cmap.green[i] = info->cmap.green[i + cmap.start];
                cmap.blue[i] = info->cmap.blue[i + cmap.start];
                cmap.transp[i] = info->cmap.transp[i + cmap.start];
